{
  "items": [
    {
      "name": "MvPolynomial.sum_monomial_eq",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {A : Type u_2} [AddCommMonoid A] {u : σ →₀ ℕ} {r : R} {b : (σ →₀ ℕ) → R → A} (w : b u 0 = 0) : ((MvPolynomial.monomial u) r).coeff.sum b = b u r",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.mul_def",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {p q : MvPolynomial σ R} : p * q = p.coeff.sum fun m a => q.coeff.sum fun n b => (MvPolynomial.monomial (m + n)) (a * b)",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.monomial_finsupp_sum_index",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {α : Type u_2} {β : Type u_3} [Zero β] (f : α →₀ β) (g : α → β → σ →₀ ℕ) (a : R) : (MvPolynomial.monomial (f.sum g)) a = MvPolynomial.C a * f.prod fun a b => (MvPolynomial.monomial (g a b)) 1",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.totalDegree_monomial_le",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (s : σ →₀ ℕ) (c : R) : ((MvPolynomial.monomial s) c).totalDegree ≤ s.sum fun x => id",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "MvPolynomial.totalDegree_monomial",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (s : σ →₀ ℕ) {c : R} (hc : c ≠ 0) : ((MvPolynomial.monomial s) c).totalDegree = s.sum fun x e => e",
      "module": "Mathlib.Algebra.MvPolynomial.Degrees"
    },
    {
      "name": "Algebra.Generators.comp_σ",
      "type": " {R : Type u} {S : Type v} {ι : Type w} [CommRing R] [CommRing S] [Algebra R S] {ι' : Type u_1} {T : Type u_2} [CommRing T] [Algebra R T] [Algebra S T] [IsScalarTower R S T] (Q : Algebra.Generators S T ι') (P : Algebra.Generators R S ι) (x : T) : (Q.comp P).σ x = (Q.σ x).coeff.sum fun n r => (MvPolynomial.rename Sum.inr) (P.σ r) * (MvPolynomial.monomial (Finsupp.mapDomain Sum.inl n)) 1",
      "module": "Mathlib.RingTheory.Extension.Generators"
    },
    {
      "name": "MvPolynomial.mkDerivationₗ_monomial",
      "type": " {σ : Type u_1} {R : Type u_2} {A : Type u_3} [CommSemiring R] [AddCommMonoid A] [Module R A] [Module (MvPolynomial σ R) A] (f : σ → A) (s : σ →₀ ℕ) (r : R) : (MvPolynomial.mkDerivationₗ R f) ((MvPolynomial.monomial s) r) = r • s.sum fun i k => (MvPolynomial.monomial (s - fun₀ | i => 1)) ↑k • f i",
      "module": "Mathlib.Algebra.MvPolynomial.Derivation"
    },
    {
      "name": "MvPolynomial.mkDerivation_monomial",
      "type": " {σ : Type u_1} (R : Type u_2) {A : Type u_3} [CommSemiring R] [AddCommMonoid A] [Module R A] [Module (MvPolynomial σ R) A] [IsScalarTower R (MvPolynomial σ R) A] (f : σ → A) (s : σ →₀ ℕ) (r : R) : (MvPolynomial.mkDerivation R f) ((MvPolynomial.monomial s) r) = r • s.sum fun i k => (MvPolynomial.monomial (s - fun₀ | i => 1)) ↑k • f i",
      "module": "Mathlib.Algebra.MvPolynomial.Derivation"
    }
  ]
}
